import {depthCopy,depthReadingText} from './depth-window-content.mjs';
import {createDepth,cloneDepth,changeDepth,depthModel,compareDepth,depthTankGeometry,depthFace,depthExample} from './depth-window-core.mjs';
import {hearButton,spoken,stopSpeech} from './play-media.mjs';

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bytes=x=>{try{return JSON.stringify(x);}catch{return null;}};
const p=t=>`<p>${esc(t)}</p>`;
const meters=n=>`${n} ${n===1?'meter':'meters'}`;
const button=(action,label,disabled=false)=>`<button type="button" data-dw-action="${action}"${disabled?' disabled':''}>${esc(label)}</button>`;
let current=null;
export function resetDepthWindow(){current=null;stopSpeech();}
function visit(book,owner){
 if(!book||typeof book!=='object'||typeof owner!=='string'||!owner.trim())return null;
 if(!current||current.book!==book||current.owner!==owner)current={book,owner,work:createDepth(),pin:null,page:'work',frame:0,caller:'work',gauge:'a',face:'top',disclosure:false,generation:0,root:null};
 return current;
}
const reading=(g,id)=>depthReadingText(g,id.toUpperCase());
function readouts(m,only=null){return `<div class="dw-readings">${(only?[only]:['a','b']).map(id=>`<p data-dw-reading="${id}" data-status="${m.gauges[id].status}">${esc(reading(m.gauges[id],id))}</p>`).join('')}</div>${m.empty?p(depthCopy.empty):''}`;}
function tank(work,previousLevel=null){
 const m=depthModel(work),g=depthTankGeometry(work),t=g.tank;
 return `<figure class="dw-tank"><svg data-dw-tank viewBox="0 0 600 460" role="img" aria-label="Still-water tank. Heights are measured above its fixed bottom; depths start at the waterline."><rect class="dw-tank-air" x="${t.xLeft}" y="${t.top}" width="${t.tankSpan}" height="${t.bottom-t.top}"/>${g.water?`<rect data-dw-water x="${g.water.x}" y="${g.water.y}" width="${g.water.width}" height="${g.water.height}"/>`:''}<path class="dw-tank-wall" d="M${t.xLeft} ${t.top}V${t.bottom}H${t.xLeft+t.tankSpan}V${t.top}"/>${g.surfaceY!==null?`<line data-dw-surface x1="${t.xLeft}" x2="${t.xLeft+t.tankSpan}" y1="${g.surfaceY}" y2="${g.surfaceY}"/><text x="${t.xLeft+8}" y="${g.surfaceY-10}">Waterline: ${meters(m.level)}</text>`:''}${previousLevel!==null?`<line data-dw-previous x1="${t.xLeft}" x2="${t.xLeft+t.tankSpan}" y1="${400-50*previousLevel}" y2="${400-50*previousLevel}"/><text class="dw-previous-label" x="${t.xLeft+8}" y="${400-50*previousLevel-10}">Earlier waterline: ${meters(previousLevel)}</text>`:''}${['a','b'].map(id=>{const a=g.gauges[id],b=a.bracket;return `${b?(b.zero?`<circle data-dw-zero="${id}" cx="${b.x}" cy="${b.y1}" r="4"/>`:`<g class="dw-depth"><line data-dw-depth="${id}" x1="${b.x}" x2="${b.x}" y1="${b.y1}" y2="${b.y2}"/><path d="M${b.x-6} ${b.y1}h12M${b.x-6} ${b.y2}h12"/></g>`):''}<g data-dw-probe="${id}" transform="translate(${a.x} ${a.y})">${id==='a'?'<circle r="10"/>':'<path d="M0 -12L12 0 0 12 -12 0Z"/>'}<text x="0" y="${g.surfaceY!==null&&a.y===g.surfaceY?32:-19}" text-anchor="middle">${id.toUpperCase()}</text></g>`;}).join('')}<g class="dw-ruler"><line x1="${g.ruler.x}" x2="${g.ruler.x}" y1="50" y2="400"/>${g.ruler.ticks.map(tick=>`<g><line data-dw-tick="${tick.height}" x1="${g.ruler.x-7}" x2="${g.ruler.x+4}" y1="${tick.y}" y2="${tick.y}"/><text x="${g.ruler.x+10}" y="${tick.y+5}">${tick.height}</text></g>`).join('')}</g><text x="300" y="435" text-anchor="middle">Fixed bottom · height zero</text><text x="300" y="455" text-anchor="middle">Ruler: height above bottom (meters)</text></svg><figcaption>Lettered dots mark reading locations, not bodies drawn to scale.</figcaption></figure>`;
}
function controls(w){return `<div class="dw-controls" aria-label="Still-water setup controls">${[['level','Waterline above bottom',0,6],['a','Gauge A height above bottom',1,6],['b','Gauge B height above bottom',1,6]].map(([key,label,start,end])=>`<label>${label}<select data-dw-field="${key}">${Array.from({length:end-start+1},(_,i)=>i+start).map(n=>`<option value="${n}"${w[key]===n?' selected':''}>${meters(n)}</option>`).join('')}</select></label>`).join('')}<label>Tank setup<select data-dw-field="width">${['narrow','wide'].map(n=>`<option value="${n}"${n===w.width?' selected':''}>${n==='narrow'?'Narrow':'Wide'}</option>`).join('')}</select></label></div>`;}
function workPage(v){const m=depthModel(v.work);return `${p(depthCopy.instruction)}<div class="dw-bench"><div>${tank(v.work)}${readouts(m)}</div>${controls(v.work)}</div>${p(depthCopy.conservationNote)}<div class="dw-actions">${button('pin',v.pin?'Replace pinned setup':'Pin this setup')}${button('compare','Compare with pinned',!v.pin)}${button('faces','Turn a test face')}${button('example','Show a separate example')}</div>${p(v.pin?depthCopy.pinned:depthCopy.noPin)}`;}
function table(work,kind){const m=depthModel(work);return `<table data-dw-setup="${kind}"><caption>${kind==='pinned'?'Pinned setup':'Current setup'}</caption><tbody><tr><th scope="row">Waterline above bottom</th><td>${meters(m.level)}</td></tr><tr><th scope="row">Tank setup</th><td>${m.width==='wide'?'Wide':'Narrow'}</td></tr>${['a','b'].map(id=>`<tr><th scope="row">Gauge ${id.toUpperCase()}</th><td data-status="${m.gauges[id].status}">${esc(reading(m.gauges[id],id))}</td></tr>`).join('')}</tbody></table>`;}
function comparison(v){const c=compareDepth(v.pin,v.work);return `<h3>Pinned and current tank</h3>${p(c.text)}<div class="dw-comparison">${table(v.pin,'pinned')}${table(v.work,'current')}</div><div class="dw-actions">${button('back','Back to my tank')}${button('example','Show a separate example')}</div>`;}
function faces(v){const f=depthFace(v.work,v.gauge,v.face),a=f.arrow,b=f.backing,s=f.segment;return `<h3>Turn a tiny test face</h3><label class="dw-gauge-select">Gauge to examine<select data-dw-gauge>${['a','b'].map(id=>`<option value="${id}"${id===v.gauge?' selected':''}>${id.toUpperCase()}</option>`).join('')}</select></label>${readouts(depthModel(v.work),v.gauge)}<div class="dw-actions" role="group" aria-label="Test face orientation">${['top','bottom','left','right'].map(id=>`<button type="button" data-dw-face-choice="${id}" aria-pressed="${v.face===id}">${id[0].toUpperCase()+id.slice(1)}${v.face===id?' · selected':''}</button>`).join('')}</div><figure class="dw-face"><svg data-dw-face viewBox="0 0 300 210" role="img" aria-label="${esc(v.face)} test face${a?', with a force arrow perpendicular into its exposed water side':', without a water-force arrow'}"><rect data-dw-backing x="${b.x}" y="${b.y}" width="${b.width}" height="${b.height}"/><line data-dw-segment x1="${s.x1}" y1="${s.y1}" x2="${s.x2}" y2="${s.y2}"/>${a?`<line data-dw-force x1="${a.x1}" y1="${a.y1}" x2="${a.x2}" y2="${a.y2}"/><polygon data-dw-arrowhead points="${a.head.map(pt=>`${pt.x},${pt.y}`).join(' ')}"/>`:''}<text x="${v.face==='left'?65:v.face==='right'?235:150}" y="${v.face==='bottom'?185:v.face==='top'?28:65}" text-anchor="middle">${a?'Water side':'Test face'}</text><text x="150" y="201" text-anchor="middle">Magnified local schematic</text></svg><figcaption>${esc(depthCopy.faceLimit)}</figcaption></figure>${!a?p(depthCopy.facePrompt):''}${p(depthCopy.pressureDefinition)}${p(depthCopy.faceExplanation)}${p(depthCopy.depthContrast)}<div class="dw-actions">${button('back','Back to my tank')}${button('example','Show a separate example')}</div>`;}
function example(v){const e=depthExample(v.frame);return `<h3>A separate example</h3>${p(`Picture ${v.frame+1} of 6. ${e.text}`)}${tank(e.work,e.previousLevel)}${readouts(depthModel(e.work))}<div class="dw-actions">${button('previous','Previous',v.frame===0)}${button('next','Next',v.frame===5)}${button('back',v.caller==='comparison'?'Back to comparison':v.caller==='faces'?'Back to test face':'Back to my tank')}</div>`;}
export function depthWindowPage(book,owner){const v=visit(book,owner);if(!v)return '';v.generation++;return `<section class="dw-page" data-dw-root data-dw-view="${v.page}" data-dw-frame="${v.frame}"><header><h2 id="dw-heading" tabindex="-1">Depth Window</h2>${v.page==='work'?p(depthCopy.story):''}</header><div class="dw-mat">${v.page==='example'?example(v):v.page==='comparison'?comparison(v):v.page==='faces'?faces(v):workPage(v)}<div class="dw-actions">${hearButton('',`Read this ${v.page==='work'?'tank':v.page==='comparison'?'comparison':v.page==='faces'?'face':'example'}`).replace('data-speak=', 'data-dw-hear data-speak=')}</div><details data-dw-disclosure${v.disclosure?' open':''}><summary>For grown-ups</summary>${p(depthCopy.grownUp)}</details>${p(depthCopy.visit)}</div></section>`;}
function narration(root){function read(n){if(n.nodeType===3)return n.textContent+' ';if(n.nodeType!==1)return '';if(n.matches('svg,button,[hidden],[aria-hidden="true"],.speech-controls,drawn-howto'))return '';const css=getComputedStyle(n);if(css.display==='none'||css.visibility==='hidden')return '';if(n.matches('select'))return (n.selectedOptions[0]?.textContent||'')+'. ';if(n.matches('[data-dw-face-choice]'))return '';if(n.tagName==='DETAILS'&&!n.open)return '';return [...n.childNodes].map(read).join(' ');}return spoken(read(root).replace(/\s+/g,' ').trim());}
// Controls never become live again after an ancestry or visibility mutation.
function bindingGuard(root,valid,stop){
 const controls=[root,...root.querySelectorAll('button,select,a,details,summary')].filter(n=>!n.closest('.speech-controls,drawn-howto')),chains=new Map(),retired=new WeakSet();let disconnected=false;
 const chain=n=>{const out=[];for(;n;n=n.parentNode)out.push(n);return out;};controls.forEach(n=>chains.set(n,chain(n)));
 const audit=records=>{for(const r of records){if(r.target.closest?.('.speech-controls,drawn-howto'))continue;if(r.type==='attributes'){for(const n of controls)if(chains.get(n).includes(r.target))retired.add(n);}else for(const removed of r.removedNodes)for(const n of controls)if(chains.get(n).includes(removed)||removed.contains?.(n))retired.add(n);}};
 const observer=new MutationObserver(records=>{audit(records);if(!root.isConnected||!valid()||retired.has(root)){stop();observer.disconnect();disconnected=true;}});
 observer.observe(document,{childList:true,subtree:true,attributes:true,attributeFilter:['hidden','inert','aria-hidden','style','class']});
 return n=>{audit(observer.takeRecords());if(disconnected||!valid()||!root.isConnected||!root.contains(n)||retired.has(n)||n.disabled)return false;const before=chains.get(n),now=chain(n);if(!before||before.length!==now.length||!before.every((p,i)=>p===now[i]))return false;for(let el=n;el?.nodeType===1;el=el.parentElement){const css=getComputedStyle(el);if(el.hidden||el.inert||el.getAttribute('aria-hidden')==='true'||css.display==='none'||['hidden','collapse'].includes(css.visibility))return false;if(el.tagName==='DETAILS'&&!el.open&&el!==n&&!el.querySelector(':scope>summary')?.contains(n))return false;}return n.getClientRects().length>0;};
}
export function bindDepthWindow(book,ctx={}){
 const owner=typeof ctx.explorerId==='function'?ctx.explorerId():ctx.explorerId,v=current,root=document.querySelector('[data-dw-root]');if(!v||v.book!==book||v.owner!==owner||!root)return;
 const {work,pin,page,frame,caller,gauge,face,generation}=v,workBytes=bytes(work),pinBytes=bytes(pin),route=location.hash;v.root=root;
 const stop=()=>{stopSpeech();ctx.stopSpeech?.();ctx.stopSound?.();};
 const valid=()=>current===v&&v.root===root&&v.generation===generation&&v.work===work&&bytes(work)===workBytes&&v.pin===pin&&bytes(pin)===pinBytes&&v.page===page&&v.frame===frame&&v.caller===caller&&v.gauge===gauge&&v.face===face&&(typeof ctx.notebook==='function'?ctx.notebook():ctx.notebook)===book&&(typeof ctx.explorerId==='function'?ctx.explorerId():ctx.explorerId)===owner&&ctx.isActive?.()===true&&location.hash===route&&route==='#science/ice'&&document.querySelector('[data-dw-root]')===root;
 const live=bindingGuard(root,valid,stop);
 for(const n of root.querySelectorAll('button,select,a,details,summary')){if(n.closest('.speech-controls,drawn-howto'))continue;for(const type of ['click','change','input','keydown'])n.addEventListener(type,e=>{if(!live(n)){e.preventDefault();e.stopImmediatePropagation();}},{capture:true});}
 const redraw=(selector='#dw-heading')=>{stop();ctx.render?.();const n=document.querySelector('[data-dw-root]')?.querySelector(selector);if(n&&!n.disabled){n.focus({preventScroll:true});const b=n.getBoundingClientRect();if(b.top<0||b.bottom>innerHeight)n.scrollIntoView({block:'nearest'});}};
 for(const n of root.querySelectorAll('[data-dw-field]'))n.addEventListener('change',()=>{if(!live(n))return;const key=n.dataset.dwField,value=key==='width'?n.value:/^\d$/.test(n.value)?Number(n.value):null,next=changeDepth(work,key,value);if(!next||next===work)return;v.work=next;redraw(`[data-dw-field="${key}"]`);});
 root.querySelector('[data-dw-gauge]')?.addEventListener('change',e=>{const n=e.currentTarget;if(!live(n)||!['a','b'].includes(n.value)||n.value===gauge)return;v.gauge=n.value;redraw('[data-dw-gauge]');});
 for(const n of root.querySelectorAll('[data-dw-face-choice]'))n.addEventListener('click',()=>{if(!live(n)||!['top','bottom','left','right'].includes(n.dataset.dwFaceChoice)||n.dataset.dwFaceChoice===face)return;v.face=n.dataset.dwFaceChoice;redraw(`[data-dw-face-choice="${v.face}"]`);});
 root.querySelector('[data-dw-disclosure]')?.addEventListener('toggle',e=>{if(live(e.currentTarget)){stop();v.disclosure=e.currentTarget.open;}});
 root.querySelector('[data-dw-hear]')?.addEventListener('click',e=>{if(live(e.currentTarget)){const selected=page==='faces'?` Selected test face: ${face}.`:'';e.currentTarget.dataset.speak=narration(root)+selected;}},{capture:true});
 for(const n of root.querySelectorAll('[data-dw-action]'))n.addEventListener('click',()=>{if(!live(n))return;const action=n.dataset.dwAction;if(action==='pin'){v.pin=cloneDepth(work);redraw('[data-dw-action="pin"]');}else if(action==='compare'&&pin){v.page='comparison';redraw();}else if(action==='faces'){v.page='faces';redraw();}else if(action==='example'){v.caller=page;v.page='example';v.frame=0;redraw();}else if(action==='back'){v.page=page==='example'?caller:'work';redraw(`[data-dw-action="${page==='example'?'example':page==='faces'?'faces':'compare'}"]`);}else if(['previous','next'].includes(action)){const next=frame+(action==='next'?1:-1);if(next<0||next>5)return;v.frame=next;redraw(`[data-dw-action="${next===5?'previous':next===0?'next':action}"]`);}});
}
